function johnsons(n, edges) {
  // Virtual node n connected to all vertices with weight 0.
  const augmented = [...edges];
  for (let v = 0; v < n; v++) augmented.push([n, v, 0]);
  const h = new Array(n + 1).fill(Infinity);
  h[n] = 0;
  for (let i = 0; i < n; i++) {
    for (const [u, v, w] of augmented) {
      if (h[u] !== Infinity && h[u] + w < h[v]) h[v] = h[u] + w;
    }
  }
  // Reweight to non-negative edges.
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) adj[u].push([v, w + h[u] - h[v]]);
  const result = [];
  for (let src = 0; src < n; src++) {
    const dist = new Array(n).fill(Infinity);
    dist[src] = 0;
    const pq = [[0, src]];
    while (pq.length) {
      pq.sort((a, b) => a[0] - b[0]);
      const [d, u] = pq.shift();
      if (d > dist[u]) continue;
      for (const [v, w] of adj[u]) {
        if (d + w < dist[v]) {
          dist[v] = d + w;
          pq.push([dist[v], v]);
        }
      }
    }
    result.push(dist.map((d, v) => (d === Infinity ? Infinity : d + h[v] - h[src])));
  }
  return result;
}

